/**
 * 0050_media_store.sql 结构自证（离线 · 零 DB · 零网络）
 * ---------------------------------------------------------------------
 * 用法：node ops/media-upload/backend/readings/check-migration-0050.cjs
 * 判据面（派单边界：迁移不由本单 apply —— apply 归 Zang；本脚本只证「文件形态 = 契约」）：
 *   A. 语句面：CREATE TABLE IF NOT EXISTS public.media 恰 1 · CREATE INDEX IF NOT EXISTS 恰 1 ·
 *      DO $$ 自检块恰 1；**零 BEGIN / COMMIT 语句**（migrate.ts 逐文件包事务，文件内禁写）。
 *   B. 列面：7 列逐字在场（media_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY /
 *      sha256 char(64) NOT NULL / content_type text NOT NULL CHECK(三值闭集) / bytes bytea NOT NULL /
 *      size_bytes integer NOT NULL CHECK(>0 AND <=2097152) / owner_uid bigint NOT NULL REFERENCES
 *      public.users(uid) / time_created timestamptz NOT NULL DEFAULT now()）+ 约束名
 *      media_sha256_size_uniq UNIQUE (sha256, size_bytes)。
 *   C. 加法面：零 UPDATE / DELETE / DROP / ALTER / TRUNCATE 语句（零动既有表 · 0001–0049 不动）。
 *   D. 括号面：$$ 计数为偶（DO 块闭合）· 圆括号平衡。
 */
const fs = require('fs');
const path = require('path');

const REPO = path.resolve(__dirname, '..', '..', '..', '..');
const file = path.join(REPO, 'backend-ts', 'migrations', '0050_media_store.sql');
const raw = fs.readFileSync(file, 'utf8');

// 去 `--` 行注释后的语句体（判据用；注释里的 BEGIN/COMMIT 字样不构成语句）
const code = raw.split('\n').filter((l) => !/^\s*--/.test(l)).join('\n');
const codeLower = code.toLowerCase();

const checks = [];
const t = (id, what, pass, reading) => { checks.push({ id, what, pass, reading }); if (!pass) process.exitCode = 1; };

const countOf = (re) => (raw.match(re) ?? []).length;

// A. 语句面
t('A1', 'CREATE TABLE IF NOT EXISTS public.media 恰 1 处', countOf(/CREATE TABLE IF NOT EXISTS public\.media/g) === 1, `count=${countOf(/CREATE TABLE IF NOT EXISTS public\.media/g)}`);
t('A2', 'CREATE INDEX IF NOT EXISTS media_sha256_idx 恰 1 处', countOf(/CREATE INDEX IF NOT EXISTS media_sha256_idx/g) === 1, `count=${countOf(/CREATE INDEX IF NOT EXISTS media_sha256_idx/g)}`);
t('A3', 'DO $$ 自检块恰 1 处', countOf(/^\s*DO \$\$/gm) === 1, `count=${countOf(/^\s*DO \$\$/gm)}`);
t('A4', '语句体零 BEGIN / COMMIT（migrate.ts 包事务）', !/(^|;)\s*(BEGIN|COMMIT)\b/m.test(codeLower), 'code body has no BEGIN/COMMIT statement');
t('A5', '零 END TRANSACTION / START TRANSACTION', !/(start|end)\s+transaction/i.test(codeLower), 'absent');

// B. 列面（逐字契约 = data-layer.spec v0.34 §40.1 / 派单 DDL）
const mustContain = [
  ['B1', 'media_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY', /media_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY/],
  ['B2', 'sha256 char(64) NOT NULL', /sha256 char\(64\) NOT NULL/],
  ['B3', "content_type text NOT NULL CHECK (content_type IN ('image/webp','image/jpeg','image/png'))", /content_type text NOT NULL CHECK \(content_type IN \('image\/webp','image\/jpeg','image\/png'\)\)/],
  ['B4', 'bytes bytea NOT NULL', /bytes bytea NOT NULL/],
  ['B5', 'size_bytes integer NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 2097152)', /size_bytes integer NOT NULL CHECK \(size_bytes > 0 AND size_bytes <= 2097152\)/],
  ['B6', 'owner_uid bigint NOT NULL REFERENCES public.users(uid)', /owner_uid bigint NOT NULL REFERENCES public\.users\(uid\)/],
  ['B7', 'time_created timestamptz NOT NULL DEFAULT now()', /time_created timestamptz NOT NULL DEFAULT now\(\)/],
  ['B8', 'CONSTRAINT media_sha256_size_uniq UNIQUE (sha256, size_bytes)', /CONSTRAINT media_sha256_size_uniq UNIQUE \(sha256, size_bytes\)/],
  ['B9', '自检块断言 7 列类型映射（character(64) 等 format_type 口径）', /'sha256',\s+'character\(64\)'/],
  ['B10', '自检块断言 identity = BY DEFAULT（attidentity = d）', /attidentity = % \(expect d = BY DEFAULT\)/],
];
for (const [id, what, re] of mustContain) t(id, what, re.test(raw), 'present');

// C. 加法面（语句体零写改既有对象）
t('C1', '零 UPDATE 语句', !/(^|;)\s*UPDATE\b/m.test(codeLower), 'absent');
t('C2', '零 DELETE / TRUNCATE 语句', !/(^|;)\s*(DELETE FROM|TRUNCATE)\b/m.test(codeLower), 'absent');
t('C3', '零 DROP / ALTER / GRANT / REVOKE 语句', !/(^|;)\s*(DROP|ALTER|GRANT|REVOKE)\b/m.test(codeLower), 'absent');
t('C4', '既有表名零出现（零动既有表 · 只允许 users 出现在 FK 与 0050 自身）', (() => {
  const existing = ['listing', 'prize_item', 'account', 'ledger_entry', 'currency', 'batt_account', 'schema_migration'];
  const hits = existing.filter((name) => new RegExp(`\\b${name}\\b`).test(codeLower));
  return hits.length === 0;
})(), 'no pre-existing table referenced (besides users FK / new media table)');

// D. 括号面
const dollars = (raw.match(/\$\$/g) ?? []).length;
t('D1', '$$ 计数为偶（DO 块闭合）', dollars % 2 === 0, `count=${dollars}`);
const parens = (code.match(/\(/g) ?? []).length - (code.match(/\)/g) ?? []).length;
t('D2', '语句体圆括号平衡', parens === 0, `balance=${parens}`);

console.log(JSON.stringify({
  script: 'ops/media-upload/backend/readings/check-migration-0050.cjs',
  file: 'backend-ts/migrations/0050_media_store.sql',
  bytes: raw.length,
  summary: { total: checks.length, passed: checks.filter((c) => c.pass).length, failed: checks.filter((c) => !c.pass).length },
  checks,
}, null, 1));
